/**
 * Deep Shaft offline app shell.
 *
 * Hand-written rather than generated by a build plugin, so the cache list cannot come from
 * `src/data/`. Instead it is *derived from the built shell at install time*: the worker caches
 * `index.html`, reads back the asset URLs that build references (hashed bundle names, stylesheet,
 * manifest, icons), and caches those too. A hardcoded list would 404 on the next build.
 *
 * Version the cache by bumping CACHE_NAME. On activation every superseded cache is deleted, so a
 * player never keeps serving a stale bundle.
 */

const CACHE_NAME = 'deep-shaft-v1';

/** The documents a navigation can land on. Everything else is read out of the built HTML. */
const SHELL_DOCUMENTS = ['./', './index.html'];

/** File types worth keeping: the shell and its assets, not API responses. */
const CACHEABLE = /\.(?:css|js|mjs|png|svg|jpg|jpeg|webp|ico|webmanifest|woff2?)(?:\?|$)/;

/**
 * Cache lookup options for the app shell.
 *
 * `ignoreVary` is load-bearing, not a nicety. Servers commonly tag the shell with `Vary: Origin`
 * (Vite's preview server does), while a cached entry filled by `cache.add()` carries no `Origin`
 * header. A `crossorigin` script or stylesheet request *does* send one, so a header-sensitive
 * lookup misses the entry that is sitting right there and the offline load fails. Only same-origin
 * requests reach this handler, so varying on origin has no meaning here.
 */
const SHELL_LOOKUP = Object.freeze({ ignoreSearch: true, ignoreVary: true });

function absolute(url) {
  return new URL(url, self.location.href).href;
}

async function cacheShell() {
  const cache = await caches.open(CACHE_NAME);
  await cache.addAll(SHELL_DOCUMENTS.map(absolute));

  const response = await cache.match(absolute('./index.html'));
  if (!response) {
    return;
  }

  const html = await response.text();
  const referenced = [...html.matchAll(/(?:src|href)="([^"]+)"/g)]
    .map((match) => match[1])
    .filter((url) => !url.startsWith('http') && url !== '#')
    .map(absolute);

  // One unreachable asset must not fail the whole install: the app shell alone is still playable.
  await Promise.all(
    [...new Set(referenced)].map((url) => cache.add(url).catch(() => undefined)),
  );
}

self.addEventListener('install', (event) => {
  event.waitUntil(
    cacheShell().then(() => self.skipWaiting()),
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      const names = await caches.keys();
      await Promise.all(names.filter((name) => name !== CACHE_NAME).map((name) => caches.delete(name)));
      await self.clients.claim();
    })(),
  );
});

self.addEventListener('fetch', (event) => {
  const { request } = event;
  if (request.method !== 'GET') {
    return;
  }

  const url = new URL(request.url);
  if (url.origin !== self.location.origin) {
    return;
  }

  event.respondWith(
    (async () => {
      const cached = await caches.match(request, SHELL_LOOKUP);
      if (cached) {
        return cached;
      }

      try {
        const response = await fetch(request);
        // Keep the shell current: an asset that changed since install replaces its cached copy.
        if (response.ok && (CACHEABLE.test(url.pathname) || request.mode === 'navigate')) {
          const cache = await caches.open(CACHE_NAME);
          cache.put(request, response.clone());
        }
        return response;
      } catch (error) {
        // Offline and uncached: fall back to the shell so the app still boots, and let anything
        // that genuinely has no offline answer fail as it normally would.
        const shell = await caches.match(absolute('./index.html'), SHELL_LOOKUP);
        if (shell && request.mode === 'navigate') {
          return shell;
        }
        throw error;
      }
    })(),
  );
});
